package studyfix.assignment.persistence;

import studyfix.Identity;
import studyfix.assignment.model.GradingResult;
import java.sql.*;
import java.util.*;
import static studyfix.assignment.protocol.AssignmentJson.*;

/** Durable Week assignments. No room membership, session or online presence is stored here. */
public final class WeekAssignmentRepository {
 private final AssignmentRepository repo;
 public WeekAssignmentRepository(AssignmentRepository repo)throws SQLException{this.repo=repo;try(var c=repo.open();var s=c.createStatement()){
  s.executeUpdate("CREATE TABLE IF NOT EXISTS p3_week_dispatches(id TEXT PRIMARY KEY,owner_id TEXT NOT NULL,week_id TEXT NOT NULL,week_no INTEGER NOT NULL,title TEXT NOT NULL,description TEXT NOT NULL,deadline_at INTEGER NOT NULL,closed INTEGER NOT NULL DEFAULT 0,revision INTEGER NOT NULL DEFAULT 1,request_key TEXT NOT NULL,request_hash TEXT NOT NULL,created_at INTEGER NOT NULL,UNIQUE(owner_id,request_key))");
  s.executeUpdate("CREATE TABLE IF NOT EXISTS p3_week_work(id TEXT PRIMARY KEY,dispatch_id TEXT NOT NULL REFERENCES p3_week_dispatches(id),exercise_id TEXT NOT NULL REFERENCES p3_exercises(id),root_id TEXT NOT NULL,display_code TEXT NOT NULL,title TEXT NOT NULL,ordinal_no INTEGER NOT NULL,UNIQUE(dispatch_id,root_id))");
  s.executeUpdate("CREATE TABLE IF NOT EXISTS p3_week_receivers(work_id TEXT NOT NULL REFERENCES p3_week_work(id),user_id TEXT NOT NULL,owner_id TEXT NOT NULL,week_id TEXT NOT NULL,root_id TEXT NOT NULL,username TEXT NOT NULL,display_name TEXT NOT NULL,student_code TEXT NOT NULL,classes_json TEXT NOT NULL,PRIMARY KEY(work_id,user_id),UNIQUE(owner_id,week_id,root_id,user_id))");
  s.executeUpdate("CREATE TABLE IF NOT EXISTS p3_week_submissions(id TEXT PRIMARY KEY,work_id TEXT NOT NULL REFERENCES p3_week_work(id),user_id TEXT NOT NULL,request_key TEXT NOT NULL,source_code TEXT NOT NULL,is_run INTEGER NOT NULL,status TEXT NOT NULL,verdict TEXT NOT NULL,score REAL NOT NULL DEFAULT 0,passed_tests INTEGER NOT NULL DEFAULT 0,total_tests INTEGER NOT NULL DEFAULT 0,feedback TEXT NOT NULL DEFAULT '',duration_ms INTEGER NOT NULL DEFAULT 0,test_results_json TEXT NOT NULL DEFAULT '[]',created_at INTEGER NOT NULL,UNIQUE(user_id,request_key))");
  s.executeUpdate("CREATE INDEX IF NOT EXISTS p3_week_receivers_user ON p3_week_receivers(user_id,week_id)");s.executeUpdate("CREATE INDEX IF NOT EXISTS p3_week_submissions_work ON p3_week_submissions(work_id,user_id,created_at)");
 }}
 private static List<Map<String,Object>> rows(Connection c,String sql,Object... values)throws SQLException{try(var p=c.prepareStatement(sql)){for(int i=0;i<values.length;i++)p.setObject(i+1,values[i]);try(var r=p.executeQuery()){List<Map<String,Object>> out=new ArrayList<>();var meta=r.getMetaData();while(r.next()){Map<String,Object> row=new LinkedHashMap<>();for(int j=1;j<=meta.getColumnCount();j++)row.put(meta.getColumnLabel(j),r.getObject(j));out.add(row);}return out;}}}
 private static Map<String,Object> first(List<Map<String,Object>> rows){return rows.isEmpty()?new LinkedHashMap<>():rows.getFirst();}
 private static void update(Connection c,String sql,Object... values)throws SQLException{try(var p=c.prepareStatement(sql)){for(int i=0;i<values.length;i++)p.setObject(i+1,values[i]);p.executeUpdate();}}
 public Map<String,Object> create(Identity who,String week,List<String> exercises,List<Map<String,Object>> receivers,long deadline,String key,String hash)throws SQLException{
  try(var c=repo.open();var tx=c.createStatement()){tx.execute("BEGIN IMMEDIATE");try{
   var previous=first(rows(c,"SELECT id,request_hash FROM p3_week_dispatches WHERE owner_id=? AND request_key=?",who.userId(),key));if(!previous.isEmpty()){if(!hash.equals(previous.get("request_hash")))throw new IllegalArgumentException("Mã giao bài đã dùng cho nội dung khác.");tx.execute("COMMIT");return mapOf("dispatchId",previous.get("id"),"reused",true);}
   var w=first(rows(c,"SELECT * FROM p3_question_weeks WHERE id=?",week));if(w.isEmpty())throw new IllegalArgumentException("Week không còn tồn tại.");
   List<Map<String,Object>> selected=new ArrayList<>();for(String exercise:exercises){var q=first(rows(c,"SELECT e.id,e.title,b.root_id,b.display_code FROM p3_question_week_items wi JOIN p3_exercises e ON e.id=wi.exercise_id JOIN p3_question_bank b ON b.exercise_id=e.id WHERE wi.week_id=? AND e.id=? AND b.deleted=0 AND b.is_current=1 AND b.publication='PUBLISHED' AND b.bank_scope='PRACTICE' AND e.mode='BUILD_FROM_SCRATCH'",week,exercise));if(q.isEmpty())throw new IllegalArgumentException("Chỉ giao bài Lập trình từ đầu đã phát hành, thuộc Luyện tập và nằm trong Week: "+exercise);selected.add(q);}
   for(var q:selected)for(var user:receivers)if(!rows(c,"SELECT 1 FROM p3_week_receivers WHERE owner_id=? AND week_id=? AND root_id=? AND user_id=?",who.userId(),week,q.get("root_id"),user.get("id")).isEmpty())throw new IllegalArgumentException("Bài "+q.get("display_code")+" đã được giao trong Week cho "+user.get("name")+". Bỏ người/bài đã giao trước khi xác nhận.");
   String id=UUID.randomUUID().toString();long now=System.currentTimeMillis();update(c,"INSERT INTO p3_week_dispatches VALUES(?,?,?,?,?,?,?,0,1,?,?,?)",id,who.userId(),week,w.get("week_no"),w.get("title"),w.get("description"),deadline,key,hash,now);
   int order=0;for(var q:selected){String work=UUID.randomUUID().toString();update(c,"INSERT INTO p3_week_work VALUES(?,?,?,?,?,?,?)",work,id,q.get("id"),q.get("root_id"),q.get("display_code"),q.get("title"),++order);for(var user:receivers)update(c,"INSERT INTO p3_week_receivers VALUES(?,?,?,?,?,?,?,?,?)",work,user.get("id"),who.userId(),week,q.get("root_id"),user.get("username"),user.get("name"),user.get("studentCode"),stringify(user.get("classes")));}
   tx.execute("COMMIT");return mapOf("dispatchId",id,"reused",false,"questions",selected.size(),"students",receivers.size());
  }catch(SQLException|RuntimeException e){tx.execute("ROLLBACK");throw e;}}
 }
 private static final String WORK="SELECT w.id AS workId,w.exercise_id AS exerciseId,w.display_code AS code,w.title,w.ordinal_no AS ordinal,d.id AS dispatchId,d.owner_id AS ownerId,d.week_id AS weekId,d.week_no AS weekNo,d.title AS weekTitle,d.deadline_at AS deadlineAt,d.closed,d.revision,d.created_at AS assignedAt,r.user_id AS userId,r.username,r.display_name AS displayName,r.student_code AS studentCode,r.classes_json AS classesJson FROM p3_week_work w JOIN p3_week_dispatches d ON d.id=w.dispatch_id JOIN p3_week_receivers r ON r.work_id=w.id";
 public Map<String,Object> work(String work,String user)throws SQLException{try(var c=repo.open()){var row=first(rows(c,WORK+" WHERE w.id=? AND r.user_id=?",work,user));if(row.isEmpty())throw new SecurityException("Bạn không được giao bài này.");return row;}}
 private static void progress(Connection c,Map<String,Object> row)throws SQLException{
  var p=first(rows(c,"SELECT COUNT(*) AS attempts,COALESCE(MAX(CASE WHEN status='DONE' THEN score ELSE 0 END),0) AS bestScore,COALESCE(MAX(CASE WHEN verdict='ACCEPTED' AND status='DONE' THEN 1 ELSE 0 END),0) AS accepted,COALESCE(MAX(CASE WHEN status IN ('QUEUED','RUNNING') THEN 1 ELSE 0 END),0) AS pending FROM p3_week_submissions WHERE work_id=? AND user_id=? AND is_run=0",row.get("workId"),row.get("userId")));row.putAll(p);row.put("submitted",number(p,"attempts",0)>0);row.put("accepted",number(p,"accepted",0)>0);row.put("pending",number(p,"pending",0)>0);row.put("closed",number(row,"closed",0)!=0);row.put("expired",number(row,"deadlineAt",0)>0&&System.currentTimeMillis()>=number(row,"deadlineAt",0));row.put("classes",list(parse(text(row,"classesJson","[]"))));row.remove("classesJson");
 }
 public List<Map<String,Object>> studentWork(Identity who,String classId)throws SQLException{try(var c=repo.open()){var out=rows(c,WORK+" WHERE r.user_id=? AND EXISTS(SELECT 1 FROM json_each(r.classes_json) j WHERE json_extract(j.value,'$.id')=?) ORDER BY d.created_at,w.ordinal_no",who.userId(),classId);for(var row:out)progress(c,row);return out;}}
 public List<Map<String,Object>> teacherProgress(Identity who,String week,String classId,Set<String> allowedStudents)throws SQLException{try(var c=repo.open()){var out=rows(c,WORK+" WHERE d.owner_id=? AND d.week_id=? AND (?='' OR EXISTS(SELECT 1 FROM json_each(r.classes_json) j WHERE json_extract(j.value,'$.id')=?)) ORDER BY d.created_at DESC,r.display_name,w.ordinal_no",who.userId(),week,classId,classId).stream().filter(r->allowedStudents.contains(text(r,"userId",""))).toList();for(var row:out)progress(c,row);return out;}}
 public List<Map<String,Object>> timelineWeeks()throws SQLException{try(var c=repo.open()){return rows(c,"SELECT id,week_no AS weekNo,title,description FROM p3_question_weeks ORDER BY week_no");}}
 public List<Map<String,Object>> archivedWeeks(Identity who)throws SQLException{try(var c=repo.open()){return rows(c,"SELECT d.week_id AS id,d.week_no AS weekNo,d.title,d.description FROM p3_week_dispatches d WHERE d.owner_id=? AND NOT EXISTS(SELECT 1 FROM p3_question_weeks w WHERE w.id=d.week_id) AND d.created_at=(SELECT MIN(x.created_at) FROM p3_week_dispatches x WHERE x.owner_id=d.owner_id AND x.week_id=d.week_id) GROUP BY d.week_id",who.userId());}}
 public Map<String,Object> dispatch(Identity who,String id)throws SQLException{try(var c=repo.open()){var row=first(rows(c,"SELECT * FROM p3_week_dispatches WHERE id=? AND owner_id=?",id,who.userId()));if(row.isEmpty())throw new SecurityException("Đợt giao bài không thuộc bạn.");return row;}}
 public Set<String> dispatchClasses(Identity who,String id)throws SQLException{dispatch(who,id);try(var c=repo.open()){Set<String> ids=new HashSet<>();for(var row:rows(c,"SELECT DISTINCT json_extract(j.value,'$.id') AS id FROM p3_week_receivers r JOIN p3_week_work w ON w.id=r.work_id,json_each(r.classes_json) j WHERE w.dispatch_id=?",id))ids.add(text(row,"id",""));return ids;}}
 public void control(Identity who,String id,int revision,String action,long deadline)throws SQLException{dispatch(who,id);try(var c=repo.open();var p=c.prepareStatement("UPDATE p3_week_dispatches SET deadline_at=CASE WHEN ?='EXTEND' THEN ? ELSE deadline_at END,closed=CASE WHEN ?='CLOSE' THEN 1 WHEN ?='OPEN' THEN 0 ELSE closed END,revision=revision+1 WHERE id=? AND owner_id=? AND revision=?")){p.setString(1,action);p.setLong(2,deadline);p.setString(3,action);p.setString(4,action);p.setString(5,id);p.setString(6,who.userId());p.setInt(7,revision);if(p.executeUpdate()!=1)throw new IllegalStateException("Đợt giao đã thay đổi, hãy tải lại.");}}
 public Map<String,Object> submit(Identity who,String work,String key,String source,boolean run)throws SQLException{
  try(var c=repo.open();var tx=c.createStatement()){tx.execute("BEGIN IMMEDIATE");try{
   var old=first(rows(c,"SELECT id,work_id,source_code,is_run FROM p3_week_submissions WHERE user_id=? AND request_key=?",who.userId(),key));if(!old.isEmpty()){if(!work.equals(old.get("work_id"))||!source.equals(old.get("source_code"))||run!=(number(old,"is_run",0)!=0))throw new IllegalArgumentException("Mã nộp bài đã dùng cho nội dung khác.");tx.execute("COMMIT");return mapOf("id",old.get("id"),"created",false);}
   var assigned=first(rows(c,WORK+" WHERE w.id=? AND r.user_id=?",work,who.userId()));if(assigned.isEmpty())throw new SecurityException("Bài chưa được giao cho bạn.");long now=System.currentTimeMillis();if(number(assigned,"closed",0)!=0||number(assigned,"deadlineAt",0)>0&&now>=number(assigned,"deadlineAt",0))throw new IllegalStateException("Bài đã đóng hoặc quá hạn nộp.");
   String id=UUID.randomUUID().toString();update(c,"INSERT INTO p3_week_submissions(id,work_id,user_id,request_key,source_code,is_run,status,verdict,created_at) VALUES(?,?,?,?,?,?,'QUEUED','QUEUED',?)",id,work,who.userId(),key,source,run?1:0,now);tx.execute("COMMIT");return mapOf("id",id,"created",true);
  }catch(SQLException|RuntimeException e){tx.execute("ROLLBACK");throw e;}}
 }
 public Map<String,Object> rawSubmission(String id)throws SQLException{try(var c=repo.open()){var row=first(rows(c,"SELECT s.*,w.exercise_id AS exerciseId FROM p3_week_submissions s JOIN p3_week_work w ON w.id=s.work_id WHERE s.id=?",id));if(row.isEmpty())throw new IllegalArgumentException("Không tìm thấy bài nộp.");return row;}}
 public Map<String,Object> result(String id)throws SQLException{try(var c=repo.open()){var r=rawSubmission(id);return mapOf("id",id,"workId",r.get("work_id"),"userId",r.get("user_id"),"sourceCode",r.get("source_code"),"isRun",number(r,"is_run",0)!=0,"status",r.get("status"),"verdict",r.get("verdict"),"score",r.get("score"),"maxScore",100,"passedTests",r.get("passed_tests"),"totalTests",r.get("total_tests"),"feedback",r.get("feedback"),"durationMs",r.get("duration_ms"),"submittedAt",r.get("created_at"),"testResults",list(parse(text(r,"test_results_json","[]"))),"structureResults",StructureResultStore.read(c,id));}}
 public List<Map<String,Object>> history(String work,String user)throws SQLException{try(var c=repo.open()){return rows(c,"SELECT id,is_run AS isRun,status,verdict,score,created_at AS submittedAt FROM p3_week_submissions WHERE work_id=? AND user_id=? ORDER BY created_at DESC,id DESC LIMIT 50",work,user);}}
 public List<String> recover()throws SQLException{try(var c=repo.open()){update(c,"UPDATE p3_week_submissions SET status='QUEUED',verdict='QUEUED' WHERE status='RUNNING'");return rows(c,"SELECT id FROM p3_week_submissions WHERE status='QUEUED' ORDER BY created_at").stream().map(r->text(r,"id","")).toList();}}
 public void running(String id)throws SQLException{try(var c=repo.open()){update(c,"UPDATE p3_week_submissions SET status='RUNNING',verdict='RUNNING' WHERE id=? AND status='QUEUED'",id);}}
 public void finish(String id,GradingResult result)throws SQLException{try(var c=repo.open()){c.setAutoCommit(false);try{update(c,"UPDATE p3_week_submissions SET status='DONE',verdict=?,score=?,passed_tests=?,total_tests=?,feedback=?,duration_ms=?,test_results_json=? WHERE id=?",result.verdict(),result.score(),result.passed(),result.total(),result.feedback(),result.durationMillis(),stringify(result.publicTests()),id);StructureResultStore.write(c,id,result.structureResults());c.commit();}catch(SQLException|RuntimeException e){c.rollback();throw e;}}}
}
